// Field geometry (generated by scripts/gen-field.mjs) + AprilTags (published
// by the robot sim from the same WPILib layout the robot code loads).
import field2026 from './field-2026.json';
import fieldB8 from './field-b8.json';
import { nt } from '../nt/store';

/** What the Field dropdown offers: the two official 2026 builds, and our practice space B8. */
export type Variant = 'andymark' | 'welded' | 'b8';
export type ElementType = 'solid' | 'bump' | 'low-clearance' | 'marking';
/** What the robot sim loads for a view (/Sim/Control/field): the game field or B8. */
export type SimField = '2026' | 'b8';

export interface FieldElement {
  id: string;
  name: string;
  type: ElementType;
  alliance: 'blue' | 'red';
  poly: [number, number][];
  heightM?: number;
  cite: string;
  approx?: boolean;
}

/** One field as the UI draws it and the robot sim simulates it. */
export interface FieldDef {
  /** Title in the top bar. */
  game: string;
  length: number;
  width: number;
  elements: FieldElement[];
  /** Official 2026 field only: alliance zones, starting lines, center line, alliance walls. */
  startingLineFromWallM?: number;
  hubCenters?: { blue: [number, number]; red: [number, number] };
  /** Practice field: draw a grid this far apart (m). */
  gridM?: number;
  /** AprilTags are expected here (a hint shows until the sim sends them). */
  hasTags: boolean;
  simField: SimField;
}

export interface Tag {
  id: number;
  x: number;
  y: number;
  z: number;
  yaw: number;
  pitch: number;
}

/** Game-wide numbers (2026 REBUILT): auto length, preload, robot rules. */
export const FIELD = field2026 as unknown as {
  game: string;
  startingLineFromWallM: number;
  autoDurationS: number;
  fuelPreloadMax: number;
  /** HUB scoring opening: hexagon, flat sides facing ±Y (field drawings: 41.73 in across the flats, rim at 72 in). */
  hubOpening: { acrossFlatsM: number; heightM: number; flatsFacing: 'Y' };
  robotRules: { maxPerimeterM: number; maxHeightM: number; maxBumperExtensionM: number; minBumperFoamM: number };
  variants: Record<'andymark' | 'welded', {
    length: number;
    width: number;
    hubCenters: { blue: [number, number]; red: [number, number] };
    elements: FieldElement[];
  }>;
};

const B8 = fieldB8 as unknown as { game: string; length: number; width: number; gridM: number; elements: FieldElement[] };

const official = (v: 'andymark' | 'welded'): FieldDef => ({
  game: FIELD.game, ...FIELD.variants[v], startingLineFromWallM: FIELD.startingLineFromWallM, hasTags: true, simField: '2026',
});

export const FIELDS: Record<Variant, FieldDef> = {
  andymark: official('andymark'),
  welded: official('welded'),
  // Team 9520's practice space: a plain 15 ft × 11 ft rectangle, no tags or elements yet
  b8: { game: B8.game, length: B8.length, width: B8.width, elements: B8.elements, gridM: B8.gridM, hasTags: false, simField: 'b8' },
};

export const VARIANT_LABEL: Record<Variant, string> = {
  andymark: 'AndyMark',
  welded: 'Welded',
  b8: 'B8 practice (15 × 11 ft)',
};

export const isVariant = (v: unknown): v is Variant => typeof v === 'string' && v in FIELDS;

/** Tags as published by the robot sim (/Sim/Field/tags/<variant>). Empty until connected. */
export function getTags(variant: Variant): Tag[] {
  const flat = nt.get(`/Sim/Field/tags/${variant}`) as number[] | undefined;
  if (!Array.isArray(flat)) return [];
  const tags: Tag[] = [];
  for (let i = 0; i + 5 < flat.length; i += 6) {
    tags.push({ id: flat[i], x: flat[i + 1], y: flat[i + 2], z: flat[i + 3], yaw: flat[i + 4], pitch: flat[i + 5] });
  }
  return tags;
}
